<?php require_once __DIR__."/../config/auth.php";require_role(["admin"]);$pdo=db();if($_SERVER["REQUEST_METHOD"]==="POST"){try{check_csrf($_POST["csrf"]??"");if($_POST["action"]==="open"){if(cash_session())throw new Exception("Session already open.");$pdo->prepare("INSERT INTO cash_sessions(user_id,opened_at,opening_cash) VALUES(?,NOW(),?)")->execute([user()["id"],max(0,(float)$_POST["cash"])]);$_SESSION["flash"]=["type"=>"ok","msg"=>"Session opened."];}else{$cs=cash_session();if(!$cs)throw new Exception("No open session.");$q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN payment_method='cash' THEN total ELSE 0 END),0) cash,COALESCE(SUM(CASE WHEN payment_method='card' THEN total ELSE 0 END),0) card,COALESCE(SUM(CASE WHEN payment_method='other' THEN total ELSE 0 END),0) other,COUNT(*) cnt FROM invoices WHERE cash_session_id=? AND status<>'cancelled'");$q->execute([$cs["id"]]);$x=$q->fetch();$expected=$cs["opening_cash"]+$x["cash"]; $pdo->prepare("UPDATE cash_sessions SET closed_at=NOW(),closing_cash=?,expected_cash=?,cash_sales=?,card_sales=?,other_sales=?,sales_count=?,status='closed' WHERE id=?")->execute([(float)$_POST["cash"],$expected,$x["cash"],$x["card"],$x["other"],$x["cnt"],$cs["id"]]);$_SESSION["flash"]=["type"=>"ok","msg"=>"Day closed. Expected cash: ".number_format($expected,2)." EGP"];}}catch(Throwable $e){$_SESSION["flash"]=["type"=>"bad","msg"=>$e->getMessage()];}redirect("closing.php");}$cs=cash_session();include __DIR__."/partials/header.php";?><header><h1><?=t("تقفيل اليوم","Day Closing")?></h1></header><?php if($cs):?><div class="card"><h2><?=t("الجلسة مفتوحة","Session Open")?></h2><p>Opening cash: <b><?=number_format($cs["opening_cash"],2)?></b></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="close"><label><?=t("النقد الفعلي في الدرج","Actual cash")?><input name="cash" type="number" step=".01" required></label><button class="btn primary"><?=t("تقفيل","Close Day")?></button></form></div><?php else:?><div class="card"><h2><?=t("فتح جلسة","Open Session")?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="open"><label><?=t("رصيد بداية الدرج","Opening cash")?><input name="cash" type="number" step=".01" value="0" required></label><button class="btn primary">Open</button></form></div><?php endif;?><?php include __DIR__."/partials/footer.php";?>